package io.github.hienpham0344.stayfinder.notification;
import io.github.hienpham0344.stayfinder.notification.service.NotificationService;import io.github.hienpham0344.stayfinder.notification.repository.NotificationRepository;import io.github.hienpham0344.stayfinder.notification.entity.Notification;
import io.github.hienpham0344.stayfinder.common.events.*;import io.github.hienpham0344.stayfinder.common.idempotency.IdempotencyLockRepository;import io.github.hienpham0344.stayfinder.user.service.UserPreferencesService;import io.github.hienpham0344.stayfinder.user.dto.PreferencesResponse;import io.github.hienpham0344.stayfinder.booking.repository.BookingRepository;import io.github.hienpham0344.stayfinder.booking.entity.Booking;import io.github.hienpham0344.stayfinder.common.exception.BusinessException;
import org.junit.jupiter.api.*;import jakarta.persistence.EntityManager;import java.util.*;import java.time.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class NotificationServiceTest{
 NotificationRepository rows;OutboxEventRepository events;UserPreferencesService preferences;BookingRepository bookings;NotificationService service;UUID owner=UUID.randomUUID();Instant now=Instant.parse("2026-10-13T12:00:00Z");
 @BeforeEach void setup(){rows=mock(NotificationRepository.class);events=mock(OutboxEventRepository.class);preferences=mock(UserPreferencesService.class);bookings=mock(BookingRepository.class);service=new NotificationService(rows,events,preferences,bookings,mock(IdempotencyLockRepository.class),mock(EntityManager.class),Clock.fixed(now,ZoneOffset.UTC),inboxStates());when(preferences.get(owner)).thenReturn(new PreferencesResponse("en-US",true));}
 io.github.hienpham0344.stayfinder.notification.repository.NotificationInboxStateRepository inboxStates(){var r=mock(io.github.hienpham0344.stayfinder.notification.repository.NotificationInboxStateRepository.class);Map<UUID,io.github.hienpham0344.stayfinder.notification.entity.NotificationInboxState> values=new HashMap<>();when(r.findById(any())).thenAnswer(i->Optional.ofNullable(values.get(i.getArgument(0))));when(r.saveAndFlush(any())).thenAnswer(i->{io.github.hienpham0344.stayfinder.notification.entity.NotificationInboxState s=i.getArgument(0);values.put(s.getUserId(),s);return s;});return r;}
 OutboxEvent event(String type){var e=new OutboxEvent();e.setId(UUID.randomUUID());e.setUserId(owner);e.setSourceId(UUID.randomUUID());e.setType(type);e.setOccurredAt(now.minusSeconds(60));return e;}
 @Test void materializationIsOnceAndSourceTargetIsOwned(){var e=event("booking_paid");when(bookings.findByIdAndUserId(e.getSourceId(),owner)).thenReturn(Optional.of(new Booking()));when(events.claimPendingBatch(100)).thenReturn(List.of(e));service.materializeBatch();assertEquals(now,e.getMaterializedAt());assertEquals("delivered",e.getMaterializationStatus());service.materializeBatch();verify(rows,times(1)).save(any());}
 @Test void bookingOptOutSuppressesNoticeButRewardsRemain(){when(preferences.get(owner)).thenReturn(new PreferencesResponse("vi-VN",false));var booking=event("booking_created");var reward=event("reward_claimed");when(events.claimPendingBatch(100)).thenReturn(List.of(booking,reward));service.materializeBatch();assertEquals("suppressed",booking.getMaterializationStatus());assertEquals("delivered",reward.getMaterializationStatus());verify(rows,times(1)).save(argThat(n->n.getTargetRoute().equals("rewards")&&n.getTargetResourceId()==null));}
 @Test void unownedBookingSourceCannotProduceNavigableNotification(){var e=event("booking_paid");when(events.claimPendingBatch(100)).thenReturn(List.of(e));service.materializeBatch();assertEquals("invalid_source",e.getMaterializationStatus());verify(rows,never()).save(any());}
 @Test void deliveryAfterListMustStayAfterItsCutoffEvenWhenClockHasSamePrecision(){var page=org.springframework.data.domain.PageRequest.of(0,20);when(rows.findByUserId(owner,page)).thenReturn(org.springframework.data.domain.Page.empty(page));var snapshot=service.list(owner,false,page).snapshotTime();var e=event("reward_earned");when(events.claimPendingBatch(100)).thenReturn(List.of(e));service.materializeBatch();verify(rows).save(argThat(n->n.getCreatedAt().isAfter(snapshot)));}
 @Test void markingRequiresOwnerAndReadAllUsesOriginalSnapshotCutoff(){var foreign=new Notification();foreign.setId(UUID.randomUUID());foreign.setUserId(UUID.randomUUID());when(rows.lockById(foreign.getId())).thenReturn(Optional.of(foreign));assertThrows(BusinessException.class,()->service.markRead(owner,foreign.getId()));assertNull(foreign.getReadAt());var page=org.springframework.data.domain.PageRequest.of(0,20);when(rows.findByUserId(owner,page)).thenReturn(org.springframework.data.domain.Page.empty(page));service.list(owner,false,page);Instant snapshot=now.minusSeconds(10);service.markAllRead(owner,snapshot);verify(rows).markAllRead(owner,snapshot,now);assertThrows(BusinessException.class,()->service.markAllRead(owner,now.plusSeconds(1)));}
}
